window.kbPageData["views/entry/k-7df003fe837dda7c"] = {"key":"entry/k-7df003fe837dda7c","state":{"route":"entry/k-7df003fe837dda7c"},"node":{"id":"k-7df003fe837dda7c","mode":"k","title":"市场准入负面清单","type":"制度与规则","domain":"法律","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["law","market"],"主类":["制度与规则"],"出处性质":["机构注释"],"学科":["公共管理","法律"],"来源主题":["发展与治理"],"资料类别":["非时政"]},"seeAlso":["k-46365a675a4ee2ee","k-9738a804f4964fab"],"supplement":[{"doc":"6cbfb01fe723bba64b75","file":"《2026年政府工作报告》粉笔解读.pdf","first":8,"last":8,"relation":"辨析","evidenceId":"52847914a7c5742e81ef","cardId":"5507b615e6d18124","questionId":null,"basis":"机构注释","quote":"2.市场准入负面清单市场准入负面清单分为禁止和许可两类事项。","text":"区分禁止准入、按规定条件许可准入和清单以外依法平等进入三种情形。另两类负面清单分别针对外商投资准入、跨境服务贸易。","reference":null}],"directorySummary":"区分禁止准入、按规定条件许可准入和清单以外依法平等进入三种情形。另两类负面清单分别针对外商投资准入、跨境服务贸易。","sources":[{"id":"5507b615e6d18124","label":"市场准入负面清单","topic":"发展与治理","category":"非时政","text":"2.市场准入负面清单\n市场准入负面清单分为禁止和许可两类事项。对禁止准入事项，经营主体不得进入，政\n府依法不予审批、核准，不予办理有关手续；对许可准入事项，地方各级政府要公开法律法\n规依据、技术标准、许可要求、办理流程、办理时限，制定市场准入服务规程，由经营主体\n按照规定的条件和方式合规进入；对市场准入负面清单以外的行业、领域、业务等，各类经\n营主体皆可依法平等进入。对未实施市场禁入或许可准入但按照备案管理的事项，不得以备\n案名义变相设立许可。\n——《市场准入负面清单（2025 年版）》","source":{"doc":"6cbfb01fe723bba64b75","first":8,"last":8,"page":8,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{},"terms":{"k-46365a675a4ee2ee":{"id":"k-46365a675a4ee2ee","mode":"k","type":"制度与规则","title":"跨境服务贸易负面清单管理","qs":[],"count":2},"k-9738a804f4964fab":{"id":"k-9738a804f4964fab","mode":"k","type":"制度与规则","title":"外商投资准入前国民待遇加负面清单管理","qs":[],"count":2}},"references":{},"topics":[{"slug":"law","title":"法治政府与依法行政"},{"slug":"market","title":"统一大市场与公平竞争"}],"units":{"k-7df003fe837dda7c":[]}};
